UPDATE public.journey_chapters SET title='The Spark', description='Founded by First Contact Practitioners to bring evidence-based osteoarthritis education beyond the clinic — open to anyone, anywhere in the UK.' WHERE year='2020';
UPDATE public.journey_chapters SET title='Our First 1,000 Members', description='Our resource library and peer community welcomed their first thousand active members — early proof of the appetite for clinician-led arthritis support that anyone can access.' WHERE year='2021';
UPDATE public.journey_chapters SET title='Virtual Physiotherapy Goes Live', description='Launched virtual physiotherapy consultations with HCPC-registered clinicians, removing postcode and waiting-list barriers for people living with joint pain.' WHERE year='2022';
UPDATE public.journey_chapters SET title='Clinician-Built AI Symptom Guide', description='Released an AI-assisted symptom companion, co-designed with practising physiotherapists, helping users understand flare-ups and decide on safe next steps with confidence.' WHERE year='2023';
UPDATE public.journey_chapters SET title='10,000 Lives, One Community', description='Crossed 10,000 people supported across the UK — through anti-inflammatory nutrition plans, joint-by-joint exercise programmes and one-to-one guidance from our multidisciplinary team.' WHERE year='2024';
UPDATE public.journey_chapters SET title='Embedded in Real Patient Pathways', description='Began structured collaborations with health-service teams and rheumatology specialists, embedding our tools into everyday patient journeys at a national scale.' WHERE year='2025';
UPDATE public.journey_chapters SET title='A National Movement Takes Shape', description='A defining year of campaigns, partnerships and shared programmes with leading UK health charities — multiplying reach, deepening impact, and making evidence-based joint care a name people recognise.' WHERE year='2026';